'use client'

import { useEffect, useRef, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useRouter } from 'next/navigation'
import { EyeSVG } from './EyeSVG'

const NAV_ITEMS = [
    {
        id: 'shop',
        label: 'Shop',
        kanji: '蔵',
        english: 'Storehouse',
        path: '/products',
        color: '#E91E63',
        angle: 0
    },
    {
        id: 'custom',
        label: 'Custom Order',
        kanji: '匠',
        english: 'Artisan',
        path: '/admin/products/new',
        color: '#FF9800',
        angle: 72
    },
    {
        id: 'contact',
        label: 'Contacts',
        kanji: '結',
        english: 'Connection',
        path: '/contact',
        color: '#2196F3',
        angle: 144
    },
    {
        id: 'projects',
        label: 'Projects',
        kanji: '業',
        english: 'Work',
        path: '/projects',
        color: '#4CAF50',
        angle: 216
    },
    {
        id: 'about',
        label: 'About',
        kanji: '道',
        english: 'The Way',
        path: '/about',
        color: '#9C27B0',
        angle: 288
    }
]

export default function FourierNav() {
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const router = useRouter()
    const [showEye, setShowEye] = useState(true)
    const [eyeProgress, setEyeProgress] = useState(0)
    const [hoveredItem, setHoveredItem] = useState<string | null>(null)
    const [rotation, setRotation] = useState(0)
    const [mousePos, setMousePos] = useState({ x: 0, y: 0 })

    // Mouse Tracking for Eye
    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            const x = (e.clientX - window.innerWidth / 2) / (window.innerWidth / 2)
            const y = (e.clientY - window.innerHeight / 2) / (window.innerHeight / 2)
            setMousePos({ x, y })
        }
        window.addEventListener('mousemove', handleMouseMove)
        return () => window.removeEventListener('mousemove', handleMouseMove)
    }, [])

    // Eye Intro Animation
    useEffect(() => {
        if (!showEye) return
        const duration = 2000
        const startTime = Date.now()
        const animate = () => {
            const elapsed = Date.now() - startTime
            const progress = Math.min(elapsed / duration, 1)
            const eased = 1 - Math.pow(1 - progress, 3)
            setEyeProgress(eased)
            if (progress < 1) {
                requestAnimationFrame(animate)
            } else {
                setTimeout(() => setShowEye(false), 500)
            }
        }
        animate()
    }, [showEye])

    // Autonomous Rotation
    useEffect(() => {
        const interval = setInterval(() => {
            setRotation(prev => (prev + 0.15) % 360)
        }, 50)
        return () => clearInterval(interval)
    }, [])

    // Canvas Rendering (Alchemist Circle)
    useEffect(() => {
        const canvas = canvasRef.current
        if (!canvas) return
        const ctx = canvas.getContext('2d')
        if (!ctx) return

        let animationFrameId: number

        const resize = () => {
            canvas.width = window.innerWidth
            canvas.height = window.innerHeight
        }
        window.addEventListener('resize', resize)
        resize()

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height)

            const centerX = canvas.width / 2
            const centerY = canvas.height / 2
            const orbitalRadius = 250

            // Alchemist Circle - Outer ring
            ctx.strokeStyle = 'rgba(0, 247, 255, 0.2)'
            ctx.lineWidth = 1
            ctx.beginPath()
            ctx.arc(centerX, centerY, orbitalRadius, 0, Math.PI * 2)
            ctx.stroke()

            // Alchemist Circle - Inner ring
            ctx.strokeStyle = 'rgba(179, 0, 255, 0.15)'
            ctx.beginPath()
            ctx.arc(centerX, centerY, orbitalRadius * 0.8, 0, Math.PI * 2)
            ctx.stroke()

            // Hexagonal guides
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)'
            ctx.lineWidth = 0.5
            for (let i = 0; i < 6; i++) {
                const angle = (i * 60 * Math.PI) / 180
                ctx.beginPath()
                ctx.moveTo(centerX, centerY)
                ctx.lineTo(
                    centerX + Math.cos(angle) * orbitalRadius,
                    centerY + Math.sin(angle) * orbitalRadius
                )
                ctx.stroke()
            }

            // Connecting pentagon between planets
            ctx.strokeStyle = 'rgba(0, 247, 255, 0.1)'
            ctx.lineWidth = 1
            ctx.beginPath()
            NAV_ITEMS.forEach((item, i) => {
                const angleRad = ((item.angle + rotation) * Math.PI) / 180
                const x = centerX + Math.cos(angleRad) * orbitalRadius
                const y = centerY + Math.sin(angleRad) * orbitalRadius
                if (i === 0) ctx.moveTo(x, y)
                else ctx.lineTo(x, y)
            })
            ctx.closePath()
            ctx.stroke()

            animationFrameId = requestAnimationFrame(render)
        }

        render()
        return () => {
            window.removeEventListener('resize', resize)
            cancelAnimationFrame(animationFrameId)
        }
    }, [rotation])

    const handleClick = (path: string) => router.push(path)

    const getCirclePosition = (angle: number) => {
        const rad = ((angle + rotation) * Math.PI) / 180
        const orbitalRadius = 250
        return {
            x: Math.cos(rad) * orbitalRadius,
            y: Math.sin(rad) * orbitalRadius
        }
    }

    return (
        <>
            <AnimatePresence>
                {showEye && (
                    <motion.div
                        initial={{ opacity: 1 }}
                        exit={{ opacity: 0, filter: 'blur(20px)' }}
                        transition={{ duration: 0.8 }}
                        className="fixed inset-0 z-[200] flex items-center justify-center bg-black"
                    >
                        <div className="relative">
                            <EyeSVG progress={eyeProgress} color="#00f7ff" main mousePos={mousePos} />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <div className="relative w-full min-h-screen overflow-hidden bg-black flex items-center justify-center py-20">
                <canvas ref={canvasRef} className="absolute inset-0 z-0" />

                {/* Central Eye - Size reference: ~400px */}
                <div className="relative z-10 group pointer-events-none">
                    <div className="absolute inset-0 bg-blue-500/10 blur-3xl rounded-full group-hover:bg-blue-400/20 transition-all duration-500" />
                    <EyeSVG progress={1} color={showEye ? '#fff' : '#00f7ff'} main mousePos={mousePos} />
                </div>

                {/* Orbiting Wireframe Moons - 10% of eye (40px), 30% on hover (120px) */}
                {NAV_ITEMS.map((item) => {
                    const isHovered = hoveredItem === item.id
                    const position = getCirclePosition(item.angle)

                    return (
                        <motion.div
                            key={item.id}
                            className="absolute cursor-pointer z-10 pointer-events-auto"
                            style={{
                                left: '50%',
                                top: '50%',
                                transform: `translate(calc(-50% + ${position.x}px), calc(-50% + ${position.y}px))`
                            }}
                            onMouseEnter={() => setHoveredItem(item.id)}
                            onMouseLeave={() => setHoveredItem(null)}
                            onClick={() => handleClick(item.path)}
                            animate={{
                                scale: isHovered ? 3 : 1 // 3x scale = 30% of eye size
                            }}
                            transition={{ duration: 0.3, ease: 'easeOut' }}
                        >
                            {/* Wireframe Moon - Base 40px */}
                            <div
                                className="w-10 h-10 rounded-full flex flex-col items-center justify-center relative"
                                style={{
                                    background: 'transparent',
                                    border: `1px solid ${isHovered ? item.color : 'rgba(255,255,255,0.3)'}`,
                                    boxShadow: isHovered
                                        ? `0 0 20px ${item.color}, inset 0 0 15px ${item.color}40`
                                        : '0 0 5px rgba(255,255,255,0.2)'
                                }}
                            >
                                {/* Wireframe Grid */}
                                <svg
                                    className="absolute inset-0 w-full h-full pointer-events-none"
                                    viewBox="0 0 100 100"
                                    style={{ opacity: isHovered ? 0.9 : 0.4 }}
                                >
                                    {/* Latitude lines */}
                                    {[25, 50, 75].map(y => (
                                        <ellipse
                                            key={`lat-${y}`}
                                            cx="50"
                                            cy="50"
                                            rx="48"
                                            ry={48 * Math.cos((y - 50) * Math.PI / 100)}
                                            fill="none"
                                            stroke={isHovered ? item.color : 'rgba(255,255,255,0.3)'}
                                            strokeWidth="0.5"
                                            transform={`translate(0, ${y - 50})`}
                                        />
                                    ))}

                                    {/* Longitude lines */}
                                    {[0, 45, 90, 135].map(angle => (
                                        <ellipse
                                            key={`lon-${angle}`}
                                            cx="50"
                                            cy="50"
                                            rx={48 * Math.abs(Math.cos(angle * Math.PI / 180))}
                                            ry="48"
                                            fill="none"
                                            stroke={isHovered ? item.color : 'rgba(255,255,255,0.3)'}
                                            strokeWidth="0.5"
                                        />
                                    ))}

                                    {/* Equator */}
                                    <circle
                                        cx="50"
                                        cy="50"
                                        r="48"
                                        fill="none"
                                        stroke={isHovered ? item.color : 'rgba(255,255,255,0.4)'}
                                        strokeWidth="1"
                                    />
                                </svg>

                                {/* Kanji - Only visible on hover */}
                                {isHovered && (
                                    <div className="flex flex-col items-center justify-center h-full relative z-10">
                                        <span
                                            className="text-xl font-black leading-none"
                                            style={{
                                                color: item.color,
                                                textShadow: `0 0 10px ${item.color}`
                                            }}
                                        >
                                            {item.kanji}
                                        </span>

                                        <span
                                            className="text-[6px] uppercase tracking-wider font-bold mt-0.5"
                                            style={{ color: item.color }}
                                        >
                                            {item.english}
                                        </span>
                                    </div>
                                )}
                            </div>
                        </motion.div>
                    )
                })}
            </div>
        </>
    )
}
